def radixsort(data : list) -> list:
    exp = 1
    max_value = max(data)
    while max_value // exp > 0:
        buckets = []
        for i in range(10): # create 10 buckets based on the 10 digits of base 10 (0, 1, 2, 3, ...)
            buckets.append([])
        # buckets = [[] for i in range(10)] short form for the line above

        for val in data: # sort the values into buckets based on the current checked digit
            digit = int((val // exp) % 10)
            buckets[digit].append(val)

        data = [] # clear the content of data
        for bucket in buckets: # loop in order through the buckets
            for val in bucket:
                data.append(val) # add the bucket contents to the dict
                
        exp *= 10
    return data

